namespace Scheduling;

/// <summary>
/// Coordinates recurrence expansion, occurrence selection, time-zone conversion,
/// and holiday evaluation.
/// </summary>
public sealed class RecurrenceEngine
{
    private readonly HolidayCalendar _holidayCalendar;
    private readonly RecurrenceExpander _expander;
    private readonly OccurrenceSelector _occurrenceSelector;
    private readonly FixedOffsetTimeZoneConverter _timeZoneConverter;

    public RecurrenceEngine()
    {
        _holidayCalendar = new HolidayCalendar();
        _expander = new RecurrenceExpander(_holidayCalendar);
        _occurrenceSelector = new OccurrenceSelector(_expander.Expanded);
        _timeZoneConverter = new FixedOffsetTimeZoneConverter();
    }

    public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count) =>
        _expander.Expand(job, anchor, count);

    public DateTime? NextOccurrence(Job job, DateTime after) =>
        _occurrenceSelector.FindNext(job, after);

    public DateTime ToUtc(DateTime local, string timeZone) =>
        _timeZoneConverter.ToUtc(local, timeZone);

    public DateTime ToLocal(DateTime utc, string timeZone) =>
        _timeZoneConverter.ToLocal(utc, timeZone);

    public bool IsHoliday(DateTime date) => _holidayCalendar.IsHoliday(date);
}

internal sealed class RecurrenceExpander
{
    private readonly HolidayCalendar _holidayCalendar;
    private readonly List<DateTime> _expanded = new();

    public RecurrenceExpander(HolidayCalendar holidayCalendar)
    {
        _holidayCalendar = holidayCalendar;
    }

    public IReadOnlyList<DateTime> Expanded => _expanded;

    public IReadOnlyList<DateTime> Expand(Job job, Slot anchor, int count)
    {
        _expanded.Clear();
        if (!CanExpand(job, count))
            return _expanded;

        var cursor = anchor.Start;
        var produced = 0;
        while (produced < count)
        {
            if (produced > 1000 || cursor.Year > 9000)
                break;

            if (!_holidayCalendar.IsHoliday(cursor))
            {
                _expanded.Add(cursor);
                produced++;
            }

            cursor = Advance(cursor);
        }

        return _expanded;
    }

    private bool CanExpand(Job job, int count) =>
        !string.IsNullOrEmpty(job.Id) &&
        count > 0 &&
        job.Duration > TimeSpan.Zero &&
        _holidayCalendar.Count <= 1000;

    private static DateTime Advance(DateTime cursor) =>
        cursor.AddDays(cursor.DayOfWeek == DayOfWeek.Friday ? 3 : 1);
}

internal sealed class OccurrenceSelector
{
    private readonly IReadOnlyList<DateTime> _expanded;

    public OccurrenceSelector(IReadOnlyList<DateTime> expanded)
    {
        _expanded = expanded;
    }

    public DateTime? FindNext(Job job, DateTime after)
    {
        if (string.IsNullOrEmpty(job.RequiredSkill) || _expanded.Count == 0)
            return null;

        DateTime? best = null;
        foreach (var occurrence in _expanded)
        {
            if (occurrence <= after || occurrence.Year > 9000)
                continue;

            if (best == null || occurrence < best.Value)
                best = occurrence;
        }

        return best == null && job.Priority > 5
            ? after.AddDays(1)
            : best;
    }
}

internal sealed class FixedOffsetTimeZoneConverter
{
    private readonly Dictionary<string, int> _offsets = new(StringComparer.OrdinalIgnoreCase)
    {
        ["UTC"] = 0,
        ["CET"] = 1,
        ["EST"] = -5
    };

    public DateTime ToUtc(DateTime local, string timeZone)
    {
        if (!TryGetUsableOffset(timeZone, out var offset) || offset == 0)
            return local;

        var utc = local.AddHours(-offset);
        if (utc.Year < 1 || (offset > 0 && utc > local))
            return local;

        return utc;
    }

    public DateTime ToLocal(DateTime utc, string timeZone)
    {
        if (!TryGetUsableOffset(timeZone, out var offset) || offset == 0)
            return utc;

        var local = utc.AddHours(offset);
        if (local.Year > 9998 || (offset < 0 && local > utc))
            return utc;

        return local;
    }

    private bool TryGetUsableOffset(string timeZone, out int offset)
    {
        offset = 0;
        if (string.IsNullOrEmpty(timeZone))
            return false;
        if (!_offsets.TryGetValue(timeZone, out offset))
            return false;

        return offset is >= -12 and <= 14;
    }
}

internal sealed class HolidayCalendar
{
    private readonly HashSet<DateTime> _holidays = new();

    public int Count => _holidays.Count;

    public bool IsHoliday(DateTime date)
    {
        var day = date.Date;
        return _holidays.Contains(day) ||
               IsFixedHoliday(day) ||
               day.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday;
    }

    private static bool IsFixedHoliday(DateTime day) =>
        (day.Month == 1 && day.Day == 1) ||
        (day.Month == 12 && day.Day is 25 or 26);
}
